<template>
  <div class="flex items-center justify-center min-h-screen bg-background">
    <div class="text-center">
      <q-spinner-dots size="40px" color="primary" />
      <p class="mt-4 text-base text-muted-foreground">
        {{ $t('authenticating') || 'Authenticating...' }}
      </p>
    </div>
  </div>
</template>

<script setup lang="ts">
/**
 * TokenLogin.vue - Token-based auto-login handler
 *
 * This component handles automatic authentication when users visit the app
 * with token and org_id query parameters in the URL.
 *
 * URL Pattern: https://dev.docbits.com/?token=...&org_id=...
 *
 * Flow:
 * 1. Root route detects token+org_id params and redirects here
 * 2. This component sets the auth token and org_id
 * 3. Redirects to dashboard on success, login on failure
 *
 * Security Note: External tokens bypass OAuth refresh (ignore_token_validation=true)
 */
import { notify } from 'src/components/notifications/notify';
import { onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useAuthTokenStore } from 'src/store/main';
import { SessionStorage, LocalStorage } from 'quasar';

const route = useRoute();
const router = useRouter();
const authStore = useAuthTokenStore();

onMounted(async () => {
  const token = route.query.token as string;
  const orgId = route.query.org_id as string;

  // Validate required parameters
  if (!token || !orgId) {
    console.error('[TokenLogin] Missing required parameters:', { token: !!token, orgId: !!orgId });
    notify.error('Invalid login link. Missing token or organization ID.');
    router.push('/login');
    return;
  }

  try {
    console.log('[TokenLogin] Processing token-based authentication...');

    const farFutureExpiry = new Date();
    farFutureExpiry.setFullYear(farFutureExpiry.getFullYear() + 10);

    LocalStorage.set('token_details', {
      access_token: token,
      refresh_token: '',
      expire_time: farFutureExpiry.toISOString(),
      expires_in: 315360000,
      token_type: 'Bearer',
    });

    await authStore.setAuthToken(token);
    authStore.ignore_token_validation = true;

    SessionStorage.set('active_org_id', orgId);
    window.sessionStorage.setItem('active_org_id', orgId);

    const existingUserDetails = LocalStorage.getItem('user_details') as Record<string, unknown> | null;
    LocalStorage.set('user_details', {
      ...(existingUserDetails || {}),
      org_id: orgId,
    });

    console.log('[TokenLogin] Authentication successful, redirecting to dashboard...');
    router.push('/dashboard');
  } catch (error) {
    console.error('[TokenLogin] Authentication failed:', error);
    notify.error('Authentication failed. Please try again or use the login form.');
    router.push('/login');
  }
});
</script>
